const sourceIcon: Record<ToolSource, typeof Store> = { "Connected store": Store, "Public URL": Globe2, "Specific page URL": Link2, Screenshots: Image, "Saved draft": FileStack, "Theme files": Code2, "Selected page": MousePointer2, "Selected text": FileBarChart, "Reference design": Palette, "Analysis result": Gauge };

const projectFilters: ProjectFilter[] = ["All", "Active", "Review", "Drafts", "Validation", "Completed"];
const projectMatchesFilter = (project: ProjectRecord, filter: ProjectFilter) => filter === "All" || (filter === "Active" && ["Active", "AI working"].includes(project.status)) || (filter === "Review" && project.status === "Needs review") || (filter === "Drafts" && project.status === "Draft") || (filter === "Validation" && project.status === "Validation") || (filter === "Completed" && project.status === "Completed");
const statusClass = (status: ProjectStatus) => `project-status ${status.toLowerCase().replaceAll(" ", "-")}`;

function ProjectCard({ project, onOpen }: { project: ProjectRecord; onOpen: (project: ProjectRecord) => void }) {
  const tool = tools.find(item => item.id === project.toolId);
  return <button className="panel project-card" onClick={() => onOpen(project)}><div className="project-card-main"><div className="project-card-title"><span className={statusClass(project.status)}>{project.status}</span><h2>{project.title}</h2></div><p>{project.summary}</p><div className="project-meta"><span><Wand2 size={13} /> {tool?.name ?? "Project tool"}</span><span><Store size={13} /> {project.store}</span><span><Activity size={13} /> {project.updated}</span></div></div><div className="project-card-side"><span>{project.resultCount} findings</span><ChevronRight size={18} /></div></button>;
}

function ProjectList({ onOpen }: { onOpen: (project: ProjectRecord) => void }) {
  const [filter, setFilter] = useState<ProjectFilter>("All");
  const visible = sampleProjects.filter(project => projectMatchesFilter(project, filter));
  const groups = (["Active", "AI working", "Needs review", "Draft", "Validation", "Completed"] as ProjectStatus[]).map(status => ({ status, projects: visible.filter(project => project.status === status) })).filter(group => group.projects.length);
  return <section className="project-page"><div className="page-intro project-intro"><div><span className="eyebrow">Workspace / Projects</span><h1>Projects</h1></div><button className="primary">New project <ArrowUpRight size={16} /></button></div><div className="project-toolbar"><div className="project-filter-row">{projectFilters.map(item => <button className={filter === item ? "active" : ""} onClick={() => setFilter(item)} key={item}>{item}</button>)}</div><span>{visible.length} shown</span></div><div className="project-status-groups">{groups.map(group => <section className="project-status-section" key={group.status}><div className="project-status-heading"><span className={statusClass(group.status)}>{group.status}</span><small>{group.projects.length} project{group.projects.length === 1 ? "" : "s"}</small></div><div className="project-list">{group.projects.map(project => <ProjectCard project={project} onOpen={onOpen} key={project.id} />)}</div></section>)}</div>{visible.length === 0 && <section className="panel project-empty"><FileStack size={20} /><div><h2>No projects in this view</h2><p>Choose another filter or start a tool to create a local project.</p></div><button className="secondary">Open tools</button></section>}</section>;
}

function ProjectDetail({ project, onBack, onManual, onAI, onValidate }: { project: ProjectRecord; onBack: () => void; onManual: () => void; onAI: () => void; onValidate: () => void }) {
  const [tab, setTab] = useState<"Overview" | "Results" | "Drafts" | "Activity">("Overview");
  const tool = tools.find(item => item.id === project.toolId);
  const tabContent = tab === "Results" ? <div className="project-result-list">{["Evidence captured", "Priority findings", "Recommended fixes"].map((item, index) => <article className="project-result-row" key={item}><span>0{index + 1}</span><div><strong>{item}</strong><small>{index === 0 ? `${project.source} remains linked to this project.` : index === 1 ? `${project.resultCount} local findings are ready for review.` : "Continue manually or ask AI to prepare a proposal."}</small></div><ChevronRight size={15} /></article>)}</div> : tab === "Drafts" ? <div className="project-version-list">{Array.from({ length: Math.max(project.versionCount, 1) }, (_, index) => <article className={index === 0 ? "project-version active" : "project-version"} key={index}><div><strong>{index === 0 ? project.draftLabel : `Saved version ${project.versionCount - index + 1}`}</strong><small>{index === 0 ? "Current local sample draft" : "Saved project state"}</small></div><span>{index === 0 ? "Current" : "Saved"}</span></article>)}</div> : tab === "Activity" ? <div className="project-timeline">{[["Project created", "Tool and source context saved"], ["Result ready", `${project.resultCount} findings attached to the project`], [project.status === "AI working" ? "AI proposal running" : "Current project state", project.nextAction]].map(([title, detail], index) => <article key={title}><i className={`dot-${index}`} /><div><strong>{title}</strong><small>{detail}</small></div></article>)}</div> : <><div className="project-context-grid"><article className="panel"><span className="eyebrow">Tool</span><strong>{tool?.name ?? "Project tool"}</strong><small>{tool?.category ?? "Workspace"}</small></article><article className="panel"><span className="eyebrow">Source</span><strong>{project.source}</strong><small>{project.store}</small></article><article className="panel"><span className="eyebrow">Draft</span><strong>{project.draftLabel}</strong><small>{project.versionCount} saved version{project.versionCount === 1 ? "" : "s"}</small></article><article className="panel"><span className="eyebrow">Validation</span><strong>{project.validation}</strong><small>{project.exportState}</small></article></div><section className="panel project-next-panel"><div><span className="eyebrow">Next action</span><h2>{project.nextAction}</h2><p>Continue with the same tool, source, findings, and draft context.</p></div><button className="primary" onClick={project.status === "AI working" ? onAI : onManual}>{project.status === "AI working" ? "Open AI" : "Continue"} <ArrowUpRight size={16} /></button></section></>;
  return <section className="project-page project-detail"><div className="page-intro project-intro"><div><button className="text-button project-back" onClick={onBack}><ArrowLeft size={15} /> Projects</button><h1>{project.title}</h1></div><span className={statusClass(project.status)}>{project.status}</span></div><div className="project-detail-meta"><span><Wand2 size={13} /> {tool?.name ?? "Project tool"}</span><span><Store size={13} /> {project.store}</span><span><UserRound size={13} /> {project.owner}</span><span><Activity size={13} /> {project.updated}</span></div><div className="project-tabs">{(["Overview", "Results", "Drafts", "Activity"] as const).map(item => <button className={tab === item ? "active" : ""} onClick={() => setTab(item)} key={item}>{item}{item === "Results" && <b>{project.resultCount}</b>}{item === "Drafts" && <b>{project.versionCount}</b>}</button>)}</div><div className="project-tab-content">{tabContent}</div><section className="panel project-action-strip"><button onClick={onManual}><Layers3 size={16} /><span><strong>Manual work</strong><small>{routeFor(project.toolId).title}</small></span></button><button onClick={onAI}><Sparkles size={16} /><span><strong>Use AI</strong><small>Create a reviewable proposal</small></span></button><button onClick={() => setTab("Drafts")}><Activity size={16} /><span><strong>Compare</strong><small>{project.versionCount} saved version{project.versionCount === 1 ? "" : "s"}</small></span></button><button onClick={onValidate}><ShieldCheck size={16} /><span><strong>Validate</strong><small>{project.validation}</small></span></button><button><FileBarChart size={16} /><span><strong>Export</strong><small>{project.exportState}</small></span></button></section></section>;
}

const inventoryStatusClass = (status: InventoryStatus) => `inventory-status ${status.toLowerCase().replaceAll(" ", "-")}`;

function StoreList({ onOpen }: { onOpen: (store: StoreRecord) => void }) {
  const [adding, setAdding] = useState(false);
  return <section className="store-page"><div className="page-intro store-intro"><div><span className="eyebrow">Workspace / Stores</span><h1>Stores</h1></div><button className="primary" onClick={() => setAdding(current => !current)}>{adding ? "Close" : "Add store"} <ArrowUpRight size={16} /></button></div>{adding && <section className="panel connect-store-panel"><Store size={20} /><div><strong>Connect a supported store</strong><small>Choose a provider after the UI review. No connection is created in this UI-only phase.</small></div><button className="secondary">Choose provider</button></section>}<div className="store-list">{sampleStores.map(store => <button className="panel store-card" onClick={() => onOpen(store)} key={store.id}><div className="store-card-mark">{store.name.slice(0, 1)}</div><div className="store-card-main"><div><span className={store.status === "Connected" ? "store-status connected" : "store-status attention"}>{store.status}</span><h2>{store.name}</h2></div><p>{store.provider} · {store.url}</p><div className="store-card-meta"><span><Activity size={13} /> {store.updated}</span><span><ClipboardList size={13} /> {store.projectCount} projects</span><span><Package size={13} /> {store.inventoryCount} items</span></div></div><ChevronRight size={18} /></button>)}</div></section>;
}

function InventoryOverview({ onOpen }: { onOpen: (item: InventoryItem) => void }) {
  const [filter, setFilter] = useState<"All" | InventoryStatus>("All");
  const visible = sampleInventory.filter(item => filter === "All" || item.status === filter);
  return <section className="inventory-overview"><div className="inventory-toolbar"><div className="inventory-filter-row">{(["All", "Healthy", "Low stock", "Out of stock", "Draft"] as const).map(item => <button className={filter === item ? "active" : ""} onClick={() => setFilter(item)} key={item}>{item}</button>)}</div><span>{visible.length} items</span></div><div className="inventory-summary-grid"><article className="panel"><span>Tracked</span><strong>42</strong><small>Local inventory items</small></article><article className="panel"><span>Low stock</span><strong>1</strong><small>Needs review</small></article><article className="panel"><span>Out of stock</span><strong>1</strong><small>Availability action</small></article></div><div className="inventory-list">{visible.map(item => <button className="panel inventory-card" onClick={() => onOpen(item)} key={item.id}><div className="inventory-swatch"><Package size={18} /></div><div className="inventory-card-main"><div><span className={inventoryStatusClass(item.status)}>{item.status}</span><h3>{item.name}</h3></div><p>{item.sku} · {item.category}</p><div className="inventory-card-meta"><span>{item.stock} in stock</span><span>{item.reserved} reserved</span><span>{item.price}</span></div></div><ChevronRight size={17} /></button>)}</div>{visible.length === 0 && <section className="panel project-empty"><Archive size={20} /><div><h2>No items in this view</h2><p>Choose another inventory filter.</p></div></section>}</section>;
}

function InventoryItemDetail({ item, onBack, onProject }: { item: InventoryItem; onBack: () => void; onProject: (project: ProjectRecord) => void }) {
  const [tab, setTab] = useState<"Overview" | "AI options" | "Activity">("Overview");
  const [aiChoice, setAIChoice] = useState<string | null>(null);
  const [reviewState, setReviewState] = useState<InventoryReviewState | null>(null);
  const project = sampleProjects.find(candidate => candidate.id === item.projectId) ?? sampleProjects[0]!;
  const selectTab = (nextTab: "Overview" | "AI options" | "Activity") => { setReviewState(null); setTab(nextTab); };
  const reviewContent = reviewState === "Findings" ? <section className="inventory-review-state"><div className="inventory-review-heading"><div><button className="text-button" onClick={() => setReviewState(null)}><ArrowLeft size={14} /> Item overview</button><span className="eyebrow">Related findings</span><h2>Product and availability context</h2></div><span className="issue-tag">2 local findings</span></div><div className="inventory-review-list"><article><CircleAlert size={16} /><div><strong>Availability expectation</strong><small>Low-stock status needs a clear customer-facing notice before the purchase decision.</small></div><span>Priority</span></article><article><Layers3 size={16} /><div><strong>Product hierarchy</strong><small>Linked to {project.title}; review product summary and CTA after the availability message is chosen.</small></div><button className="text-button" onClick={() => onProject(project)}>Open project <ArrowUpRight size={13} /></button></article></div></section> : reviewState === "Validation" ? <section className="inventory-review-state"><div className="inventory-review-heading"><div><button className="text-button" onClick={() => setReviewState(null)}><ArrowLeft size={14} /> Item overview</button><span className="eyebrow">Validation state</span><h2>Checks ready for review</h2></div><span className="inventory-review-badge waiting">Required before release</span></div><div className="inventory-check-list"><div><CheckCircle2 size={15} /><span>Preview direction</span><strong>Available</strong></div><div><CircleAlert size={15} /><span>Availability message</span><strong>Pending local confirmation</strong></div><div><ShieldCheck size={15} /><span>Release approval</span><strong>Pending</strong></div></div><p className="inventory-review-copy">This local validation state documents what must be reviewed. It does not run checks or change the connected store.</p></section> : reviewState === "Export" ? <section className="inventory-review-state"><div className="inventory-review-heading"><div><button className="text-button" onClick={() => setReviewState(null)}><ArrowLeft size={14} /> Item overview</button><span className="eyebrow">Export package</span><h2>Inventory handoff</h2></div><span className="inventory-review-badge ready">Local export ready</span></div><div className="inventory-export-grid"><article><span>Item summary</span><strong>{item.name}</strong><small>{item.sku} · {item.status}</small></article><article><span>Linked project</span><strong>{project.title}</strong><small>{project.draftLabel}</small></article><article><span>Included</span><strong>Findings + draft</strong><small>Validation state is included as context.</small></article></div><p className="inventory-review-copy">Export is represented as a local handoff package in this UI-only phase; no file is generated.</p></section> : <section className="inventory-review-state"><div className="inventory-review-heading"><div><button className="text-button" onClick={() => setReviewState(null)}><ArrowLeft size={14} /> Item overview</button><span className="eyebrow">Release gate</span><h2>Release is not available yet</h2></div><span className="inventory-review-badge blocked">Approval required</span></div><div className="inventory-check-list"><div><CheckCircle2 size={15} /><span>Connected store</span><strong>Available</strong></div><div><CircleAlert size={15} /><span>Validation review</span><strong>Required</strong></div><div><ShieldCheck size={15} /><span>Explicit approval</span><strong>Pending</strong></div></div><p className="inventory-review-copy">No publish action is shown until validation, permission, review, and explicit approval are complete.</p></section>;
  const content = reviewState ? reviewContent : tab === "AI options" ? <section className="inventory-ai-grid">{[["Improve product copy", "Prepare a reviewable product description proposal."], ["Create availability message", "Draft customer-facing copy for the current stock state."], ["Plan merchandising", "Suggest a manual merchandising direction using the linked project."]].map(([title, detail]) => <button className={aiChoice === title ? "panel inventory-ai-option active" : "panel inventory-ai-option"} onClick={() => setAIChoice(title)} key={title}><Sparkles size={17} /><div><strong>{title}</strong><small>{detail}</small></div><ChevronRight size={15} /></button>)}{aiChoice && <section className="panel ai-preview-panel"><span className="eyebrow">AI preview</span><h3>{aiChoice}</h3><p>This is a local UI preview. The user can review, edit, save, export, validate, or release the proposal before any store action is possible.</p></section>}</section> : tab === "Activity" ? <section className="project-timeline inventory-timeline"><article><i /><div><strong>Inventory item opened</strong><small>{item.updated}</small></div></article><article><i /><div><strong>Related project linked</strong><small>{project.title}</small></div></article><article><i /><div><strong>Next decision</strong><small>Review findings, work manually, or choose an AI option.</small></div></article></section> : <><div className="inventory-item-grid"><article className="panel"><span className="eyebrow">Stock</span><strong>{item.stock}</strong><small>{item.reserved} reserved</small></article><article className="panel"><span className="eyebrow">Status</span><strong>{item.status}</strong><small>{item.updated}</small></article><article className="panel"><span className="eyebrow">Price</span><strong>{item.price}</strong><small>{item.sku}</small></article><article className="panel"><span className="eyebrow">Project</span><strong>{project.title}</strong><small>{project.status}</small></article></div><section className="panel inventory-next-panel"><div><span className="eyebrow">Product context</span><h2>{item.summary}</h2><p>Use the linked project to keep product, inventory, result, and release work together.</p></div><button className="secondary" onClick={() => onProject(project)}>Open project <ArrowUpRight size={15} /></button></section><section className="panel inventory-findings-shortcut"><div><span className="eyebrow">Related findings</span><strong>2 local findings are linked to this item.</strong><small>Review the availability and product-hierarchy context before choosing a change.</small></div><button className="secondary" onClick={() => setReviewState("Findings")}>Review findings <ArrowUpRight size={15} /></button></section></>;
  return <section className="store-page inventory-detail"><div className="page-intro store-intro"><div><button className="text-button project-back" onClick={onBack}><ArrowLeft size={15} /> Inventory</button><h1>{item.name}</h1></div><span className={inventoryStatusClass(item.status)}>{item.status}</span></div><div className="project-detail-meta"><span><Tag size={13} /> {item.sku}</span><span><Package size={13} /> {item.category}</span><span><Store size={13} /> Ferix Store</span></div><div className="project-tabs"><button className={tab === "Overview" && !reviewState ? "active" : ""} onClick={() => selectTab("Overview")}>Overview</button><button className={tab === "AI options" && !reviewState ? "active" : ""} onClick={() => selectTab("AI options")}>AI options</button><button className={tab === "Activity" && !reviewState ? "active" : ""} onClick={() => selectTab("Activity")}>Activity</button></div><div className="store-tab-content">{content}</div><section className="panel inventory-action-strip"><button onClick={() => onProject(project)}><Layers3 size={16} /><span><strong>Manual work</strong><small>Open linked project</small></span></button><button onClick={() => selectTab("AI options")}><Sparkles size={16} /><span><strong>Use AI</strong><small>Reviewable options</small></span></button><button onClick={() => setReviewState("Validation")}><ShieldCheck size={16} /><span><strong>Validate</strong><small>Review requirements</small></span></button><button onClick={() => setReviewState("Export")}><FileBarChart size={16} /><span><strong>Export</strong><small>Review handoff</small></span></button><button onClick={() => setReviewState("Release")}><CheckCircle2 size={16} /><span><strong>Release</strong><small>Approval required</small></span></button></section></section>;
}

function StoreDetail({ store, onBack, onProject }: { store: StoreRecord; onBack: () => void; onProject: (project: ProjectRecord) => void }) {
  const [tab, setTab] = useState<StoreTab>("Overview");
  const [itemDetail, setItemDetail] = useState<InventoryItem | null>(null);
  if (itemDetail) return <InventoryItemDetail item={itemDetail} onBack={() => setItemDetail(null)} onProject={onProject} />;
  const storeProjects = sampleProjects.filter(project => project.store === store.name);
  const tabContent = tab === "Inventory" ? <InventoryOverview onOpen={setItemDetail} /> : tab === "Projects" ? <div className="store-project-list">{storeProjects.slice(0, 4).map(project => <ProjectCard project={project} onOpen={onProject} key={project.id} />)}</div> : tab === "Drafts" ? <div className="store-draft-list">{storeProjects.filter(project => ["Draft", "AI working", "Validation"].includes(project.status)).map(project => <article className="panel store-draft-row" key={project.id}><FileStack size={17} /><div><strong>{project.draftLabel}</strong><small>{project.title} · {project.status}</small></div><button onClick={() => onProject(project)}>Open <ChevronRight size={14} /></button></article>)}</div> : tab === "Reports" ? <div className="store-report-list">{["Storefront review", "Product content review", "Inventory handoff"].map((title, index) => <article className="panel store-report-row" key={title}><FileBarChart size={17} /><div><strong>{title}</strong><small>{index === 2 ? "Inventory export package" : "Local report preview"}</small></div><button>Export <ArrowUpRight size={14} /></button></article>)}</div> : tab === "Release" ? <><section className="panel store-release-panel"><div><span className="eyebrow">Release readiness</span><h2>{store.releaseStatus}</h2><p>Validation, permission, review, and explicit approval are required before any direct publish action can appear.</p></div><div className="release-checks"><span><CheckCircle2 size={14} /> Store connected</span><span><CircleAlert size={14} /> Validation required</span><span><ShieldCheck size={14} /> Approval pending</span></div><button className="secondary">Open release review</button></section><section className="store-release-history"><div className="panel-heading"><div><span className="eyebrow">Local release history</span><h2>Draft and handoff activity</h2></div><span className="issue-tag">Sample state</span></div>{[["Draft saved", "Homepage mobile review · Mobile revision V2", "12m ago", "Draft"], ["Validation requested", "Accessibility follow-up · 5 checks queued", "Now", "Queued"], ["Exported package", "Spring visual direction · Approved direction", "May 30", "Completed"]].map(([title, detail, updated, state]) => <article className="panel store-release-history-row" key={title}><Activity size={17} /><div><strong>{title}</strong><small>{detail}</small></div><span>{updated}</span><b>{state}</b></article>)}</section></> : <><div className="store-summary-grid"><article className="panel"><span>Health</span><strong>86</strong><small>Store signal</small></article><article className="panel"><span>Projects</span><strong>{store.projectCount}</strong><small>Across tools</small></article><article className="panel"><span>Inventory</span><strong>{store.inventoryCount}</strong><small>Tracked items</small></article><article className="panel"><span>Release</span><strong>1</strong><small>Awaiting validation</small></article></div><div className="store-overview-grid"><section className="panel store-focus-panel"><div><span className="eyebrow">Current focus</span><h2>Inventory availability review</h2><p>One item is low stock and one item needs availability messaging before release.</p></div><button className="primary" onClick={() => setTab("Inventory")}>Open inventory <ArrowUpRight size={16} /></button></section><section className="panel store-work-panel"><div className="panel-heading"><div><span className="eyebrow">Related work</span><h2>Projects</h2></div><button className="ghost" onClick={() => setTab("Projects")}>View all <ArrowUpRight size={14} /></button></div>{storeProjects.slice(0, 2).map(project => <button className="store-work-row" onClick={() => onProject(project)} key={project.id}><span className={statusClass(project.status)}>{project.status}</span><strong>{project.title}</strong><ChevronRight size={14} /></button>)}</section></div></>;
  return <section className="store-page store-detail"><div className="page-intro store-intro"><div><button className="text-button project-back" onClick={onBack}><ArrowLeft size={15} /> Stores</button><h1>{store.name}</h1></div><span className={store.status === "Connected" ? "store-status connected" : "store-status attention"}>{store.status}</span></div><div className="project-detail-meta"><span><Store size={13} /> {store.provider}</span><span><Globe2 size={13} /> {store.url}</span><span><Activity size={13} /> {store.updated}</span></div><div className="store-tabs">{(["Overview", "Inventory", "Projects", "Drafts", "Reports", "Release"] as StoreTab[]).map(item => <button className={tab === item ? "active" : ""} onClick={() => setTab(item)} key={item}>{item}{item === "Inventory" && <b>{store.inventoryCount}</b>}{item === "Projects" && <b>{store.projectCount}</b>}</button>)}</div><div className="store-tab-content">{tabContent}</div></section>;
}

function routeFor(toolId: string) {
  if (["responsive-analyzer", "mobile-ux-analyzer", "breakpoint-analyzer", "responsive-studio"].includes(toolId)) return { title: "Responsive Studio", view: "Studio" as View, publish: false };
  if (["layout-analyzer", "visual-hierarchy-analyzer", "conversion-analyzer", "navigation-analyzer", "collection-analyzer", "cart-analyzer", "product-page-analyzer", "layout-composer", "component-builder"].includes(toolId)) return { title: "Layout Composer", view: "Studio" as View, publish: false };
  if (["visual-design-analyzer", "typography-analyzer", "color-contrast-analyzer", "product-presentation-analyzer", "screenshot-analyzer", "design-reference-analyzer", "visual-style-studio"].includes(toolId)) return { title: "Visual Style Studio", view: "Studio" as View, publish: false };
  if (["cta-analyzer", "trust-credibility-analyzer", "product-content-analyzer", "content-quality-analyzer", "ai-content-improver", "product-description-generator", "cta-generator", "seo-content-generator", "seo-analyzer", "meta-generator", "heading-structure-analyzer", "accessibility-fix-assistant", "content-editor"].includes(toolId)) return { title: "Content Studio", view: "Studio" as View, publish: false };
  if (["ai-design-copilot", "ai-store-redesign"].includes(toolId)) return { title: "AI Design Copilot", view: "Redesign" as View, publish: false };
  if (["performance-analyzer", "image-optimization-analyzer", "asset-analyzer"].includes(toolId)) return { title: "Optimization Workbench", view: "Studio" as View, publish: false };
  if (["accessibility-analyzer", "developer-handoff", "technical-analyzer", "theme-code-analyzer", "image-seo-analyzer", "checkout-ux-analyzer"].includes(toolId)) return { title: "Developer Handoff", view: "Studio" as View, publish: false };
  if (toolId === "before-after-comparator") return { title: "Version & Comparison", view: "Versions" as View, publish: false };
  if (["visual-regression-analyzer", "responsive-regression-tester", "accessibility-regression-tester", "seo-regression-tester"].includes(toolId)) return { title: "Validation Workspace", view: "Validate" as View, publish: false };
  if (["publish-readiness-checker", "publish-manager", "rollback"].includes(toolId)) return { title: "Release Review", view: "Validate" as View, publish: true };
  return { title: "Evidence Workspace", view: "Analysis" as View, publish: false };
}

function sourceHint(source: ToolSource) {
  if (source === "Connected store") return "Use a connected store from the existing Store panel.";
  if (["Screenshots", "Reference design"].includes(source)) return "Attach the visual evidence this tool should inspect.";
  if (["Saved draft", "Analysis result"].includes(source)) return "Choose the existing saved project or result to continue.";
  if (source === "Theme files") return "Attach the relevant existing theme or code files.";
  if (source === "Selected text") return "Provide the exact text this tool should use.";
  return "Provide the storefront or page address this tool should inspect.";
}

function ToolView({ tool, stage, source, setSource, input, setInput, query, setQuery, onOpen, onBack, onRun, onManual, onAI, onExport }: { tool: Tool; stage: ToolStage; source: ToolSource; setSource: (source: ToolSource) => void; input: string; setInput: (input: string) => void; query: string; setQuery: (query: string) => void; onOpen: (tool: Tool) => void; onBack: () => void; onRun: () => void; onManual: () => void; onAI: () => void; onExport: () => void }) {
  const visible = tools.filter((item) => `${item.name} ${item.category} ${item.description}`.toLowerCase().includes(query.toLowerCase()));
  const groupedTools = visible.reduce<Record<string, Tool[]>>((groups, item) => { (groups[item.category] ??= []).push(item); return groups; }, {});
  const [collapsedCategories, setCollapsedCategories] = useState<Record<string, boolean>>({});
  const route = routeFor(tool.id);
  const SourceIcon = sourceIcon[source];
  if (stage === "catalog") return <><div className="page-intro"><div><span className="eyebrow">Workspace / Tools</span><h1>Tools</h1></div></div><div className="tool-category-list">{Object.entries(groupedTools).map(([category, items], categoryIndex) => { const collapsed = collapsedCategories[category] ?? categoryIndex > 0; return <section className="panel tool-category" key={category}><button className="tool-category-header" onClick={() => setCollapsedCategories((current) => ({ ...current, [category]: !collapsed }))} aria-expanded={!collapsed}><div className="tool-category-heading"><span className="eyebrow">Tool category</span><h2>{category}</h2></div><div className="tool-category-meta"><span>{items.length} {items.length === 1 ? "tool" : "tools"}</span>{collapsed ? <ChevronRight size={17} /> : <ChevronDown size={17} />}</div></button>{!collapsed && <div className="surface-grid tool-category-grid">{items.map((item, index) => <button className="panel feature-panel tool-card" onClick={() => onOpen(item)} key={item.id}><div className={`feature-icon fi-${(categoryIndex + index) % 4}`}><Wand2 size={18} /></div><h3>{item.name}</h3><small>{item.sources.length} inputs</small><ChevronRight size={16} /></button>)}</div>}</section>; })}</div></>;
  if (stage === "setup") return <><div className="page-intro"><div><span className="eyebrow">Tools / {tool.category}</span><h1>{tool.name}</h1></div><button className="secondary" onClick={onBack}><ArrowLeft size={16} /> All tools</button></div><section className="panel"><div className="panel-heading"><div><span className="eyebrow">Tool input</span><h2>Choose what this tool should use.</h2></div><span className="issue-tag">{tool.sources.length} supported inputs</span></div><p className="flow-copy">Choose one supported input.</p><div className="source-grid">{tool.sources.map((item) => { const Icon = sourceIcon[item]; return <button className={source === item ? "source-choice active" : "source-choice"} onClick={() => setSource(item)} key={item}><Icon size={18} /><span><strong>{item}</strong><small>{sourceHint(item)}</small></span><ChevronRight size={15} /></button>; })}</div></section><section className="panel flow-input-panel"><div className="panel-heading"><div><span className="eyebrow">Selected source</span><h2><SourceIcon size={17} /> {source}</h2></div></div><p className="flow-copy">{sourceHint(source)}</p>{["Screenshots", "Reference design", "Theme files"].includes(source) ? <button className="secondary"><Upload size={15} /> Attach {source === "Theme files" ? "files" : "evidence"}</button> : source === "Connected store" ? <div className="selected-store"><Store size={18} /><div><strong>Ferix Store</strong><small>Use the store already shown in the sidebar.</small></div><ChevronRight size={15} /></div> : <input className="flow-input" value={input} onChange={(event) => setInput(event.target.value)} placeholder={source === "Selected text" ? "Paste selected text" : source === "Saved draft" ? "Select a saved project or version" : "Enter storefront or page URL"} />}</section><section className="panel flow-action-panel"><div><span className="eyebrow">Next step</span><h2>Run {tool.name}</h2></div><button className="primary flow-primary" onClick={onRun}>View result <ArrowUpRight size={16} /></button></section></>;
  if (stage === "results") return <><div className="page-intro"><div><span className="eyebrow">Analysis / {tool.name}</span><h1>Results</h1></div><button className="secondary" onClick={onBack}><ArrowLeft size={16} /> Tools</button></div><section className="panel"><div className="panel-heading"><div><span className="eyebrow">Result summary</span><h2>{tool.name} findings</h2></div><span className="issue-tag">{source}</span></div><div className="surface-grid flow-result-grid">{["Evidence captured", "Priority findings", "Recommended fixes", "Project context"].map((label, index) => <article className="panel feature-panel" key={label}><div className={`feature-icon fi-${index}`}><Gauge size={18} /></div><span className="eyebrow">0{index + 1} · Result</span><h2>{label}</h2><p>{index === 0 ? `${source} is attached to this result.` : index === 1 ? "Three focused findings are ready for review." : index === 2 ? "Review fixes before choosing how to continue." : "Save this work as its own project."}</p></article>)}</div></section><section className="panel opportunity-panel"><div className="panel-heading"><div><span className="eyebrow">How to continue</span><h2>Choose the next action for this result.</h2></div><button className="ghost" onClick={onExport}>Export report <ArrowUpRight size={15} /></button></div><div className="opportunity-grid"><button className="opportunity" onClick={onManual}><div><span className="issue-tag">Manual</span><h3>Work in {route.title}</h3><p>Continue inside the correct project workspace.</p></div><ArrowUpRight size={18} /></button><button className="opportunity" onClick={onAI}><div><span className="issue-tag">AI</span><h3>Create an AI proposal</h3><p>Keep the same source and result context.</p></div><Sparkles size={18} /></button><button className="opportunity" onClick={onExport}><div><span className="issue-tag">Export</span><h3>Download a report</h3><p>Public or unconnected work can export without publishing.</p></div><FileBarChart size={18} /></button></div></section></>;
  return <><div className="page-intro"><div><span className="eyebrow">Project / {tool.name}</span><h1>{route.title}</h1></div><button className="secondary" onClick={onBack}><ArrowLeft size={16} /> Result</button></div><section className="panel empty-visual"><Layers3 size={26} /><div><h2>Project workspace ready</h2><p>Manual work and AI proposals continue here without losing the original tool or source context.</p></div><button className="primary flow-primary">Save project <CheckCircle2 size={16} /></button></section><div className="surface-grid flow-project-grid">{["Source context", "Result findings", "Recommended changes", "Project status"].map((label, index) => <section className="panel feature-panel" key={label}><div className={`feature-icon fi-${index}`}><Layers3 size={18} /></div><span className="eyebrow">0{index + 1} · Project</span><h2>{label}</h2><p>{index === 0 ? source : index === 1 ? "Result evidence remains connected." : index === 2 ? "Manual and AI actions stay scoped to this project." : "Draft ready to save, export, or validate."}</p></section>)}</div>{route.publish && source === "Connected store" && <section className="panel flow-action-panel"><div><span className="eyebrow">Release control</span><h2>Validate before publish.</h2><p>Publish appears only for an approved connected-store project after validation and release review.</p></div><button className="secondary">Open release review</button></section>}</>;
}


const previewElements = [
  ["Hero heading", "Typography and hierarchy"],
  ["Primary CTA", "Placement and contrast"],
  ["Product grid", "Columns and spacing"],
  ["Mobile navigation", "Visibility and touch targets"],
] as const;

function StorefrontPreview({ side, device, selectedElement }: { side: PreviewSide; device: PreviewDevice; selectedElement: string }) {
  const improved = side === "After";
  return <article className={"storefront-frame " + device.toLowerCase() + " " + side.toLowerCase()} aria-label={side + " storefront preview"}><div className="preview-browser"><i /><i /><i /><span>ferix.ferrixas.com</span></div><div className="preview-site"><div className="preview-site-nav"><strong>FERIX<span>RG</span></strong><span>Shop</span><span>Collections</span><span>Journal</span><b>Bag · 0</b></div><section className={"preview-hero " + (improved ? "is-after" : "is-before")}><div className="preview-copy"><span className="preview-kicker">{improved ? "Utility collection" : "Built for everyday"}</span><h3 className={selectedElement === "Hero heading" ? "is-selected" : ""}>{improved ? "Simplify the everyday." : "Everything you need for the day, in one place."}</h3><p>{improved ? "Made to work together, designed to make the routine feel lighter." : "The complete utility collection is available now, built for your home and daily routine."}</p><span className={"preview-cta " + (selectedElement === "Primary CTA" ? "is-selected" : "")}>{improved ? "Shop the collection" : "Explore products"}</span></div><div className="preview-product-visual"><div className="preview-product-badge">New</div><div className="preview-product-shape shape-one" /><div className="preview-product-shape shape-two" /></div></section><section className={"preview-products " + (selectedElement === "Product grid" ? "is-selected" : "")}><div className="preview-products-heading"><strong>{improved ? "Designed to work together" : "Popular now"}</strong><span>View all</span></div><div className="preview-product-grid">{["Utility set", "Canvas bag", "Travel case"].map((item, index) => <article key={item}><div className={"preview-product-image image-" + index} /><strong>{item}</strong><small>{index === 0 ? "$48" : index === 1 ? "$28" : "$34"}</small></article>)}</div></section></div></article>;
}

function EditorWorkspace({ tool, source, mode, setMode, onBack }: { tool: Tool; source: ToolSource; mode: EditorMode; setMode: (mode: EditorMode) => void; onBack: () => void }) {
  const route = routeFor(tool.id);
  const [device, setDevice] = useState<PreviewDevice>("Desktop");
  const [mobileSide, setMobileSide] = useState<PreviewSide>("After");
  const [selectedElement, setSelectedElement] = useState<string>("Hero heading");
  const [draftState, setDraftState] = useState("Local preview not saved");
  const [proposalOpen, setProposalOpen] = useState(mode === "AI proposal");
  const [aiRequest, setAIRequest] = useState("Make the hero clearer and improve the mobile conversion path.");
  const changeMode = (nextMode: EditorMode) => { setMode(nextMode); if (nextMode === "AI proposal") setProposalOpen(true); };
  const devices: { label: PreviewDevice; icon: typeof Monitor }[] = [{ label: "Desktop", icon: Monitor }, { label: "Tablet", icon: Tablet }, { label: "Mobile", icon: Smartphone }];
  return <section className="editor-page"><div className="page-intro editor-intro"><div><span className="eyebrow">Project / {tool.name}</span><h1>{route.title}</h1></div><button className="secondary" onClick={onBack}><ArrowLeft size={16} /> Result</button></div><section className="panel editor-context-bar"><div><span className="eyebrow">Preview context</span><strong>{source} · Ferix Store</strong><small>Before and after previews remain a local, reviewable draft until validation and approval.</small></div><span className="editor-draft-state"><Eye size={14} /> {draftState}</span></section><div className="editor-mode-row"><div className="editor-mode-switch" role="tablist" aria-label="Editing mode"><button className={mode === "Manual" ? "active" : ""} onClick={() => changeMode("Manual")} role="tab" aria-selected={mode === "Manual"}><SlidersHorizontal size={15} /> Manual editor</button><button className={mode === "AI proposal" ? "active" : ""} onClick={() => changeMode("AI proposal")} role="tab" aria-selected={mode === "AI proposal"}><Sparkles size={15} /> AI proposal</button></div><div className="preview-device-switch" aria-label="Preview device">{devices.map(item => { const Icon = item.icon; return <button className={device === item.label ? "active" : ""} onClick={() => setDevice(item.label)} aria-label={item.label + " preview"} aria-pressed={device === item.label} key={item.label}><Icon size={15} /><span>{item.label}</span></button>; })}</div></div><div className="editor-workspace-grid"><aside className="panel editor-side editor-layers"><div className="editor-side-heading"><span className="eyebrow">Page layers</span><strong>Homepage</strong></div><div className="editor-layer-list">{previewElements.map(([name, detail]) => <button className={selectedElement === name ? "active" : ""} onClick={() => setSelectedElement(name)} key={name}><Layers3 size={14} /><span><strong>{name}</strong><small>{detail}</small></span></button>)}</div><div className="editor-layer-note"><CheckCircle2 size={14} /><span>Selected layer is carried into manual and AI work.</span></div></aside><section className={"panel editor-preview-panel show-" + mobileSide.toLowerCase()}><div className="editor-preview-toolbar"><div><span className="eyebrow">Live preview</span><strong>{device} storefront</strong></div><div className="preview-side-switch" aria-label="Mobile preview side"><button className={mobileSide === "Before" ? "active" : ""} onClick={() => setMobileSide("Before")}>Before</button><button className={mobileSide === "After" ? "active" : ""} onClick={() => setMobileSide("After")}>After</button></div></div><div className="preview-comparison"><div className="preview-side-label"><span>Before</span><small>Current storefront</small></div><StorefrontPreview side="Before" device={device} selectedElement={selectedElement} /><div className="preview-side-label"><span>After</span><small>Reviewable proposal</small></div><StorefrontPreview side="After" device={device} selectedElement={selectedElement} /></div><section className="preview-change-summary"><div><span className="eyebrow">What changed</span><strong>{selectedElement}</strong></div><p>{selectedElement === "Hero heading" ? "A clearer heading, shorter supporting copy, and a stronger primary action improve scanability." : selectedElement === "Primary CTA" ? "The action is moved closer to the product direction and given a clearer visual priority." : selectedElement === "Product grid" ? "The product cards align on the same rhythm, with spacing that holds at smaller viewports." : "The compact navigation preserves key actions without crowding the mobile header."}</p></section></section><aside className="panel editor-side editor-controls">{mode === "Manual" ? <><div className="editor-side-heading"><span className="eyebrow">Manual controls</span><strong>{selectedElement}</strong></div><div className="editor-control-list"><div><span>Breakpoint</span><strong>{device}</strong></div><div><span>Typography</span><strong>Space Grotesk · 48</strong></div><div><span>Spacing</span><strong>32 px · 16 px mobile</strong></div><div><span>Visibility</span><strong>Visible on all devices</strong></div></div><div className="editor-control-note"><SlidersHorizontal size={14} /><span>Controls are scoped to the selected layer and current breakpoint.</span></div></> : <><div className="editor-side-heading"><span className="eyebrow">AI request</span><strong>Review before applying</strong></div><textarea className="editor-ai-prompt" value={aiRequest} onChange={event => setAIRequest(event.target.value)} aria-label="AI change request" /><button className="secondary editor-proposal-button" onClick={() => setProposalOpen(true)}><Sparkles size={15} /> Preview proposal</button>{proposalOpen && <div className="editor-proposal"><span className="eyebrow">Proposal summary</span><strong>Clearer hero and mobile path</strong><small>Adjust heading hierarchy, tighten the copy, move the CTA, and preserve the source content.</small><div><span>Layout</span><span>Typography</span><span>Mobile</span></div></div>}</>}</aside></div><section className="panel editor-footer"><div><span className="eyebrow">Draft and release</span><h2>Review the preview before any change is saved.</h2><p>Save creates a local draft state only. Validation, connected-store permission, review, and approval remain required before any release action.</p></div><div className="editor-footer-actions"><button className="secondary" onClick={() => setDraftState("Local preview reset")}><RotateCcw size={15} /> Reset</button><button className="secondary" onClick={() => setDraftState("Draft saved locally")}><Save size={15} /> Save draft</button><button className="primary" onClick={() => setDraftState("Ready for validation review")}><ShieldCheck size={15} /> Validate</button></div></section></section>;
}

function ViewContent({ view, setView, tool, stage, source, setSource, input, setInput, toolQuery, setToolQuery, openTool, resetTools, runTool, continueManual, continueAI, exportReport, projectDetail, openProject, closeProject, continueProjectManual, continueProjectAI, openProjectValidation, storeDetail, openStore, closeStore, editorMode, setEditorMode, returnToResults }: { view: View; setView: (view: View) => void; tool: Tool; stage: ToolStage; source: ToolSource; setSource: (source: ToolSource) => void; input: string; setInput: (input: string) => void; toolQuery: string; setToolQuery: (query: string) => void; openTool: (tool: Tool) => void; resetTools: () => void; runTool: () => void; continueManual: () => void; continueAI: () => void; exportReport: () => void; projectDetail: ProjectRecord | null; openProject: (project: ProjectRecord) => void; closeProject: () => void; continueProjectManual: () => void; continueProjectAI: () => void; openProjectValidation: () => void; storeDetail: StoreRecord | null; openStore: (store: StoreRecord) => void; closeStore: () => void; editorMode: EditorMode; setEditorMode: (mode: EditorMode) => void; returnToResults: () => void }) {
  if (view === "Stores" && storeDetail) return <StoreDetail store={storeDetail} onBack={closeStore} onProject={openProject} />;
  if (view === "Stores") return <StoreList onOpen={openStore} />;
  if (view === "Versions" && projectDetail) return <ProjectDetail project={projectDetail} onBack={closeProject} onManual={continueProjectManual} onAI={continueProjectAI} onValidate={openProjectValidation} />;
  if (view === "Versions" && stage === "catalog") return <ProjectList onOpen={openProject} />;
  if (view === "Studio" && stage === "project") return <EditorWorkspace tool={tool} source={source} mode={editorMode} setMode={setEditorMode} onBack={returnToResults} />;
  if (view === "Tools" || (stage === "results" && view === "Analysis") || (stage === "project" && ["Studio", "Redesign", "Validate", "Versions"].includes(view))) return <ToolView tool={tool} stage={stage} source={source} setSource={setSource} input={input} setInput={setInput} query={toolQuery} setQuery={setToolQuery} onOpen={openTool} onBack={resetTools} onRun={runTool} onManual={continueManual} onAI={continueAI} onExport={exportReport} />;
  if (view === "Overview") return <>
    <div className="hero-card"><div><span className="eyebrow">Workspace pulse</span><h1>Good morning, Alex.</h1><p>Your highest-value storefront work, in one view.</p><button className="primary" onClick={() => { resetTools(); setView("Tools"); }}>Run fresh analysis <ArrowUpRight size={16} /></button></div><div className="pulse-ring"><div><strong>86</strong><span>health score</span></div></div></div>
    <div className="stats-grid">{statCards.map(card => <article className={`stat-card ${card.tone}`} key={card.label}><span>{card.label}</span><strong>{card.value}<small>{card.suffix}</small></strong><em>{card.trend}</em></article>)}</div>
    <div className="content-grid"><section className="panel chart-panel"><div className="panel-heading"><div><h2>Store momentum</h2></div><button className="ghost">Last 30 days <ChevronRight size={15} /></button></div><div className="chart"><div className="chart-line" /><div className="chart-dots"><i /><i /><i /><i /><i /><i /></div><div className="chart-labels"><span>May 01</span><span>May 08</span><span>May 15</span><span>May 22</span><span>May 30</span></div></div></section><section className="panel activity-panel"><div className="panel-heading"><div><h2>Recent activity</h2></div><Activity size={17} /></div>{["Homepage analyzed", "New team member invited", "Redesign draft created", "Report exported"].map((item, index) => <div className="activity-row" key={item}><span className={`activity-dot dot-${index}`} /><div><strong>{item}</strong><small>{index + 2}h ago</small></div><ChevronRight size={15} /></div>)}</section></div>
    <section className="panel opportunity-panel"><div className="panel-heading"><div><h2>Opportunities</h2></div><button className="ghost" onClick={() => setView("Issues")}>View all <ArrowUpRight size={15} /></button></div><div className="opportunity-grid">{[{ title: "Clarify your above-the-fold offer", tag: "High impact", meta: "Homepage · 92% confidence" }, { title: "Improve mobile navigation contrast", tag: "Quick win", meta: "Mobile · 84% confidence" }, { title: "Add social proof near checkout", tag: "Medium impact", meta: "PDP · 76% confidence" }].map(item => <button className="opportunity" key={item.title} onClick={() => { resetTools(); setView("Tools"); }}><div><span className="issue-tag">{item.tag}</span><h3>{item.title}</h3><p>{item.meta}</p></div><ArrowUpRight size={18} /></button>)}</div></section>
  </>;
  const labels: Record<Exclude<View, "Overview" | "Tools" | "Stores">, [string, string, string]> = { Analysis: ["Analysis", "Review findings.", "Start"], Issues: ["Issues", "Prioritized fixes.", "Review"], Reports: ["Reports", "Shareable outputs.", "Create"], Redesign: ["Redesign", "AI concepts.", "Create"], Studio: ["Studio", "Edit your storefront.", "Open"], Validate: ["Validate", "Check before release.", "Run"], Versions: ["Versions", "Saved directions.", "Compare"], Settings: ["Settings", "Workspace controls.", "Manage"] };
  const [title, description, action] = labels[view];
  return <><div className="page-intro"><div><span className="eyebrow">Workspace / {view}</span><h1>{title}</h1></div><button className="primary">{action} <ArrowUpRight size={16} /></button></div><section className="panel concise-page-panel"><p>{description}</p></section></>;
}

export default function Workspace() {
  const [view, setView] = useState<View>("Overview"); const [editorMode, setEditorMode] = useState<EditorMode>("Manual"); const [mobileOpen, setMobileOpen] = useState(false); const [moreOpen, setMoreOpen] = useState(false); const [query, setQuery] = useState(""); const [projectDetail, setProjectDetail] = useState<ProjectRecord | null>(null); const [storeDetail, setStoreDetail] = useState<StoreRecord | null>(null);
  const [stage, setStage] = useState<ToolStage>("catalog"); const [selectedTool, setSelectedTool] = useState<Tool>(tools[0]!); const [selectedSource, setSelectedSource] = useState<ToolSource>(tools[0]!.sources[0]!); const [input, setInput] = useState(""); const [toolQuery, setToolQuery] = useState("");
  const grouped = useMemo(() => nav.reduce<Record<string, typeof nav>>((groups, item) => { (groups[item.group] ??= []).push(item); return groups; }, {}), []); const filtered = nav.filter(item => item.label.toLowerCase().includes(query.toLowerCase()));
  const resetTools = () => { setStage("catalog"); setToolQuery(""); setInput(""); };
  const openTool = (item: Tool) => { setSelectedTool(item); setSelectedSource(item.sources[0]!); setInput(""); setStage("setup"); setView("Tools"); };
  const openManual = () => { setEditorMode("Manual"); setStage("project"); setView(routeFor(selectedTool.id).view); }; const openAI = () => { setEditorMode("AI proposal"); setStage("project"); setView(routeFor(selectedTool.id).view === "Studio" ? "Studio" : "Redesign"); }; const exportReport = () => { setView("Reports"); setStage("catalog"); }; const returnToResults = () => { setStage("results"); setView("Analysis"); };
  const openProject = (project: ProjectRecord) => { const matchingTool = tools.find(item => item.id === project.toolId); if (matchingTool) { setSelectedTool(matchingTool); setSelectedSource(project.source); } setProjectDetail(project); setStage("catalog"); setView("Versions"); };
  const closeProject = () => { setProjectDetail(null); setStage("catalog"); setView("Versions"); };
  const continueProjectManual = () => { if (!projectDetail) return; setEditorMode("Manual"); setProjectDetail(null); setStage("project"); setView(routeFor(projectDetail.toolId).view); };
  const continueProjectAI = () => { if (!projectDetail) return; const targetView = routeFor(projectDetail.toolId).view; setEditorMode("AI proposal"); setProjectDetail(null); setStage("project"); setView(targetView === "Studio" ? "Studio" : "Redesign"); };
  const openProjectValidation = () => { if (!projectDetail) return; setProjectDetail(null); setStage("project"); setView("Validate"); };
  const openStore = (store: StoreRecord) => { setStoreDetail(store); setView("Stores"); setStage("catalog"); };
  const closeStore = () => { setStoreDetail(null); setView("Stores"); };
  const currentViewLabel = nav.find(item => item.view === view)?.label ?? view;
  return <div className="preview-shell"><aside className={mobileOpen ? "sidebar open" : "sidebar"}><div className="logo">FERIX<span>RG</span><small>intelligence workspace</small></div><button className="close-mobile" onClick={() => setMobileOpen(false)} aria-label="Close navigation"><X /></button><nav>{Object.entries(grouped).map(([group, items]) => <div className="nav-group" key={group}><span>{group}</span>{items.filter(item => !query || filtered.includes(item)).map(item => { const Icon = item.icon; return <button className={view === item.view ? "active" : ""} onClick={() => { setView(item.view); if (item.view === "Tools") resetTools(); if (item.view === "Versions") { setProjectDetail(null); setStage("catalog"); } if (item.view === "Stores") setStoreDetail(null); setMobileOpen(false); }} key={item.label}><Icon size={17} />{item.label}{item.view === "Issues" && <b>24</b>}</button>; })}</div>)}</nav><button className="sidebar-store" onClick={() => openStore(sampleStores[0]!)}><div className="store-mark">F</div><div><strong>Ferix Store</strong><small>Shopify · Connected</small></div><ChevronRight size={15} /></button></aside>{moreOpen && <button className="mobile-more-backdrop" onClick={() => setMoreOpen(false)} aria-label="Close More panel" />}<section className={moreOpen ? "mobile-more-panel open" : "mobile-more-panel"} aria-label="More workspace items"><div className="mobile-more-heading"><div><span className="eyebrow">Workspace</span><h2>More</h2></div><button onClick={() => setMoreOpen(false)} aria-label="Close More"><X size={18} /></button></div><div className="mobile-more-list"><span>Workspace</span>{nav.filter(item => !["Overview", "Stores", "Tools", "Versions"].includes(item.view)).map((item) => { const Icon = item.icon; return <button onClick={() => { setView(item.view); setMoreOpen(false); }} key={item.label}><Icon size={17} />{item.label}<ChevronRight size={15} /></button>; })}</div><div className="mobile-more-list"><span>Account</span>{mobileMoreItems.map((item) => { const Icon = item.icon; return <button onClick={() => { setView("Settings"); setMoreOpen(false); }} key={item.label}><Icon size={17} />{item.label}<ChevronRight size={15} /></button>; })}</div></section><main className="main"><header className="topbar"><button className="menu-button" onClick={() => setMobileOpen(true)} aria-label="Open navigation"><Menu /></button><div className="breadcrumb"><span>Workspace</span><ChevronRight size={13} /><strong>{currentViewLabel}</strong></div><div className="top-actions"><label className="search"><Search size={16} /><input placeholder={view === "Tools" ? "Search tools" : "Search workspace"} value={view === "Tools" ? toolQuery : query} onChange={event => { setQuery(event.target.value); setToolQuery(event.target.value); }} /><kbd>⌘ K</kbd></label><button className="icon-button" aria-label="Theme options"><Moon size={17} /></button><button className="icon-button notification" aria-label="Notifications"><Bell size={17} /><i /></button><button className="avatar" aria-label="Profile">AM</button></div></header><div className="page"><div className="mobile-kicker"><span className="eyebrow">LIVE WORKSPACE</span><span>Connected · Ferix Store</span></div><ViewContent view={view} setView={setView} tool={selectedTool} stage={stage} source={selectedSource} setSource={setSelectedSource} input={input} setInput={setInput} toolQuery={toolQuery} setToolQuery={setToolQuery} openTool={openTool} resetTools={resetTools} runTool={() => { setStage("results"); setView("Analysis"); }} continueManual={openManual} continueAI={openAI} exportReport={exportReport} projectDetail={projectDetail} openProject={openProject} closeProject={closeProject} continueProjectManual={continueProjectManual} continueProjectAI={continueProjectAI} openProjectValidation={openProjectValidation} editorMode={editorMode} setEditorMode={setEditorMode} returnToResults={returnToResults} storeDetail={storeDetail} openStore={openStore} closeStore={closeStore} /></div><nav className="bottom-nav" aria-label="Mobile workspace navigation">{mobileNav.map(item => { const Icon = item.icon; const active = item.label === "Project" ? stage === "project" || view === "Versions" : view === item.view; return <button className={active ? "active" : ""} onClick={() => { setView(item.view); if (item.label === "Tools") resetTools(); if (item.label === "Project") { setProjectDetail(null); setStage("catalog"); } if (item.label === "Store") setStoreDetail(null); }} key={item.label}><Icon size={17} /><span>{item.label}</span></button>; })}<button className={moreOpen ? "active" : ""} onClick={() => setMoreOpen(true)}><Menu size={17} /><span>More</span></button></nav></main></div>;
}
